mapper.select:
SELECT rownum SEQ_NO,t.* from (select his.ENTRUST_ID, his.OPER_TYPE, nvl(p.FINPROD_ABBR,p1.FINPROD_ABBR) as finprodAbbr, to_char( his.OPER_DATE, 'yyyy-MM-dd' ) OPER_DATE, to_char( his.OPER_TIME, 'hh24:mi:ss' ) OPER_TIME, his.BUSI_DES, CASE WHEN his.OPER_TYPE = '01' THEN nvl(nvl(SU2.real_name,nvl(SUR.REAL_NAME,SUB.REAL_NAME)),SU.real_name) ELSE SU.real_name END AS userId from ETR_ENTRUST_OPER_HIS his LEFT JOIN (select * from FIN_PRODUCT where 1=1
and FINPROD_TYPE2='F32'
and FINPROD_TYPE2='F01'
) p on his.ENTRUST_ID=p.FINPROD_MARKET_ID LEFT JOIN (select * from FIN_PRODUCT where 1=1
and FINPROD_TYPE2='F32'
and FINPROD_TYPE2='F01'
) p1 on his.ENTRUST_ID=p.FINPROD_ID LEFT JOIN ETR_ENTRUST EE ON his.ENTRUST_ID = EE.ENTRUST_ID LEFT JOIN REG_FIN_PRODUCT_DEAL_TOTAL reg on reg.TOTLE_TRADE_ID= his.ENTRUST_ID LEFT JOIN ibu_quote_bond iqb on iqb.QUOTE_ID= his.ENTRUST_ID LEFT JOIN SYS_USER SU ON his.user_id = SU.user_name LEFT JOIN SYS_USER SU2 ON EE.CREATE_USER = SU2.user_name LEFT JOIN SYS_USER SUR ON reg.CREATE_USER = SUR.user_name LEFT JOIN SYS_USER SUB ON iqb.CREATE_USER = SUB.user_name WHERE his.entrust_id = #{entrustId}
and his.BUSINESS_TYPE=#{busiType,jdbcType=VARCHAR}
order by his.OPER_TIME desc) t

SELECT ROWNUM AS seqNo, M.* FROM ( SELECT su.real_name as hiUser, T2.TASK_DEF_KEY_ as nodeId, T2.NAME_ as nodeName, TO_CHAR(DECODE(T2.NAME_,'交易经办',DECODE(T1.ACTION_TYPE,'new',T5.OPER_TIME,NVL(T2.END_TIME_, T2.CLAIM_TIME_)),NVL(T2.END_TIME_, T2.CLAIM_TIME_)),'hh24:mi:ss') AS operTime, NVL(T2.END_TIME_, T2.CLAIM_TIME_) as operDate, d1.ITEM_VALUE as tradeStatus, T3.FULL_MSG_ as opinions, case when T1.ACTION_TYPE='new' then '新建' when ACTION_TYPE='modify' then '修改' else '删除' end as operType, case when T1.COMPLETE_FLG='Y' then '已完成' else '未完成' end as operStatus from SYS_WFL_BUSINESS_LIST T1 left join ACT_HI_TASKINST T2 on T1.workflow_id=T2.PROC_INST_ID_ left join ACT_HI_COMMENT T3 ON T3.TASK_ID_ = T2.ID_ AND T3.PROC_INST_ID_ = T2.PROC_INST_ID_ AND T3.USER_ID_ = T2.ASSIGNEE_ left join SYS_DATADICT_LIST d1 on T1.PROCESS_STATE=d1.ITEM_CODE and d1.DICT_CODE='PROCESS_STATE' left join sys_user su on T2.ASSIGNEE_=su.user_name left join ETR_ENTRUST_OPER_HIS T5 on T1.TRADE_ID=T5.ENTRUST_ID and T5.OPER_TYPE = '01' where 1=1
AND T1.TRADE_ID in
#{item}
AND T1.TRADE_ID= #{busiCode,jdbcType=VARCHAR}
order by NVL(T2.END_TIME_, T2.CLAIM_TIME_) desc ) M
